#!/usr/bin/env bash
set -euo pipefail
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
OUT="$ROOT/App/Generated/BuildInfo.swift"
FULL="${GITHUB_SHA:-$(git -C "$ROOT" rev-parse HEAD 2>/dev/null || echo unknown)}"
if [ "$FULL" = "unknown" ]; then SHORT="unknown"; else SHORT="${FULL:0:7}"; fi
mkdir -p "$(dirname "$OUT")"
cat > "$OUT" <<SWIFT
// Generated by scripts/embed-build-info.sh — do not edit, not committed.
enum BuildInfo {
  static let commitSHA = "$SHORT"
  static let commitSHAFull = "$FULL"
}
SWIFT
